def second_largest(numbers: list[int]) -> int | None:
    if len(numbers) < 2:
        return None

    first = second = float('-inf')
    for num in numbers:
        if num > first:
            second = first
            first = num
        elif num > second and num != first:
            second = num

    return second if second != float('-inf') else None
