import heapq
from collections import defaultdict

def top_k_elements(nums: list[int], k: int) -> list[int]:
    if not nums or k <= 0:
        return []

    freq = defaultdict(int)
    first_occurrence = {}

    for idx, num in enumerate(nums):
        freq[num] += 1
        if num not in first_occurrence:
            first_occurrence[num] = idx

    heap = []
    for num in freq:
        heapq.heappush(heap, (-freq[num], first_occurrence[num], num))

    result = []
    while heap and k > 0:
        _, _, num = heapq.heappop(heap)
        result.append(num)
        k -= 1

    return result
```

