    def get_value(s: str, i: int) -> int:
        if i >= len(s):
            return 0
        current = roman_values.get(s[i], 0)
        if i + 1 < len(s) and roman_values.get(s[i+1], 0) > current:
            return roman_values.get(s[i+1], 0) - current
        return current

    total_distance = 0
    for i in range(max_len):
        val1 = get_value(w1, i)
        val2 = get_value(w2, i)
        total_distance += abs(val1 - val2)

    return total_distance
