def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from functools import lru_cache

    n = len(coins)
    if target == 0:
        return 0

    @lru_cache(maxsize=None)
    def dp(remaining: int, index: int) -> int:
        if remaining == 0:
            return 0
        if index == n or remaining < 0:
            return float('inf')

        # Option 1: Don't use the current coin type at all
        option1 = dp(remaining, index + 1)

        # Option 2: Use the current coin type up to its limit
        min_coins = float('inf')
        for used in range(0, limits[index] + 1):
            if remaining - used * coins[index] >= 0:
                min_coins = min(min_coins, dp(remaining - used * coins[index], index + 1) + used)

        return min(option1, min_coins)

    result = dp(target, 0)
    return result if result != float('inf') else -1
