def longest_bitonic_length(nums: list[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    inc = [1] * n
    dec = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j] and inc[i] < inc[j] + 1:
                inc[i] = inc[j] + 1

    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if nums[i] > nums[j] and dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    max_length = 0
    for i in range(n):
        current_length = inc[i] + dec[i] - 1
        if current_length > max_length:
            max_length = current_length

    return max_length
