from collections import deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS to find shortest path length
    parent = [-1] * n
    distance = [-1] * n
    distance[source] = 0
    q = deque([source])

    while q:
        u = q.popleft()
        for v in adj[u]:
            if distance[v] == -1:
                distance[v] = distance[u] + 1
                parent[v] = u
                q.append(v)

    if distance[target] == -1:
        return 0

    # Count paths using DP
    dp = [0] * n
    dp[source] = 1
    for u in range(n):
        if dp[u] == 0:
            continue
        for v in adj[u]:
            if distance[v] == distance[u] + 1:
                dp[v] += dp[u]

    return dp[target]
