import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    # Define regex patterns for each token type
    patterns = [
        (r'\b\d+\.\d+\b|\b\d+\b', 'NUMBER'),  # Numbers (int or float)
        (r'\b[a-zA-Z_][a-zA-Z0-9_]*\b', 'NAME'),  # Names (identifiers)
        (r'==|!=|<=|>=|\+|-|\*|/|<|>|=|\(|\)|,', 'OP')  # Operators
    ]

    tokens = []
    pos = 0
    source_len = len(source)

    while pos < source_len:
        matched = False
        for pattern, kind in patterns:
            match = re.match(pattern, source[pos:])
            if match:
                token_text = match.group(0)
                tokens.append((kind, token_text))
                pos += len(token_text)
                matched = True
                break

        if not matched:
            # Check for invalid characters or invalid dots
            if source[pos].isdigit() or source[pos] in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_':
                raise ValueError(f"Invalid token starting at position {pos}: {source[pos:pos+10]}")
            elif source[pos] == '.':
                # Check if '.' is part of a number (already handled by NUMBER pattern)
                # or if it's a standalone dot (invalid)
                if pos + 1 >= source_len or not source[pos+1].isdigit():
                    raise ValueError(f"Invalid '.' at position {pos}")
            else:
                raise ValueError(f"Invalid character at position {pos}: {source[pos:pos+10]}")

        # Skip whitespace
        while pos < source_len and source[pos].isspace():
            pos += 1

    return tokens

