def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # program counter
    executed = 0

    while pc < len(program) and executed < 1000:
        instruction = program[pc].split()
        executed += 1

        if not instruction:
            raise ValueError("Empty instruction")

        cmd = instruction[0]

        if cmd == "PUSH":
            if len(instruction) != 2:
                raise ValueError("PUSH requires exactly one argument")
            try:
                n = int(instruction[1])
                stack.append(n)
            except ValueError:
                raise ValueError("PUSH argument must be an integer")

        elif cmd == "POP":
            if not stack:
                raise ValueError("POP with empty stack")
            stack.pop()

        elif cmd == "DUP":
            if not stack:
                raise ValueError("DUP with empty stack")
            stack.append(stack[-1])

        elif cmd == "SWAP":
            if len(stack) < 2:
                raise ValueError("SWAP with less than two values")
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif cmd == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD with less than two values")
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)

        elif cmd == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB with less than two values")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)

        elif cmd == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL with less than two values")
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)

        elif cmd == "JMP":
            if len(instruction) != 2:
                raise ValueError("JMP requires exactly one argument")
            try:
                t = int(instruction[1])
                pc = t
                continue
            except ValueError:
                raise ValueError("JMP argument must be an integer")

        elif cmd == "JZ":
            if len(instruction) != 2 or not stack:
                raise ValueError("JZ requires exactly one argument and non-empty stack")
            try:
                t = int(instruction[1])
                if stack[-1] == 0:
                    pc = t
                else:
                    stack.pop()
            except ValueError:
                raise ValueError("JZ argument must be an integer")

        elif cmd == "HALT":
            break

        else:
            raise ValueError(f"Unknown instruction: {cmd}")

        pc += 1

    if executed >= 1000:
        raise RuntimeError("Too many instructions executed")

    return stack
