def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    output = []
    pc = 0  # program counter
    labels = {}
    label_ptr = 0

    # First pass: resolve labels
    for instr in program:
        if instr.endswith(':'):
            labels[instr[:-1]] = pc
        pc += 1

    pc = 0
    while pc < len(program):
        instr = program[pc].strip()
        if not instr:
            pc += 1
            continue

        if instr.endswith(':'):
            pc += 1
            continue

        if instr in labels:
            pc = labels[instr]
            continue

        parts = instr.split()
        if not parts:
            pc += 1
            continue

        cmd = parts[0]

        if cmd == 'PUSH':
            stack.append(int(parts[1]))
        elif cmd == 'POP':
            if stack:
                output.append(stack.pop())
        elif cmd == 'ADD':
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(a + b)
        elif cmd == 'SUB':
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(b - a)
        elif cmd == 'MUL':
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(a * b)
        elif cmd == 'DIV':
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(b // a)
        elif cmd == 'PRINT':
            if stack:
                output.append(stack[-1])
        elif cmd == 'DUP':
            if stack:
                stack.append(stack[-1])
        elif cmd == 'SWAP':
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(a)
                stack.append(b)
        elif cmd == 'JMP':
            if len(parts) > 1 and parts[1] in labels:
                pc = labels[parts[1]]
            else:
                pc += 1
        elif cmd == 'JZ':
            if len(stack) >= 1 and stack[-1] == 0 and len(parts) > 1 and parts[1] in labels:
