from collections import deque

def min_slides(grid: list[str]) -> int:
    rows = len(grid)
    if rows == 0:
        return -1
    cols = len(grid[0])

    # Find start and exit positions
    start = None
    exit_ = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                exit_ = (i, j)

    if not start or not exit_:
        return -1

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    queue = deque()
    queue.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    while queue:
        x, y, steps = queue.popleft()

        if (x, y) == exit_:
            return steps

        for dx, dy in directions:
            nx, ny = x, y
            # Slide until wall or boundary
            while True:
                next_x, next_y = nx + dx, ny + dy
                if 0 <= next_x < rows and 0 <= next_y < cols and grid[next_x][next_y] != '#':
                    nx, ny = next_x, next_y
                else:
                    break

            # Check if the slide was valid (changed position)
            if (nx, ny) != (x, y) and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny, steps + 1))

    return -1
