def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    def multiply(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if a[i][k] == 0:
                    continue
                for j in range(n):
                    res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % mod
        return res

    def matrix_pow(mat: list[list[int]], power: int) -> list[list[int]]:
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1

        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    if exp == 0:
        return [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    mat = [[x % mod for x in row] for row in matrix]
    return matrix_pow(mat, exp)
