from collections import deque

def min_slides(grid: list[str]) -> int:
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    # Find all starting positions ('.')
    start_positions = []
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.':
                start_positions.append((i, j))

    if not start_positions:
        return 0

    # BFS setup: queue stores (row, col, steps)
    queue = deque()
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    for pos in start_positions:
        queue.append((pos[0], pos[1], 0))
        visited[pos[0]][pos[1]] = True

    while queue:
        x, y, steps = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny]:
                if grid[nx][ny] == 'X':
                    continue  # Cannot move to 'X'
                visited[nx][ny] = True
                queue.append((nx, ny, steps + 1))

    # Count the number of visited cells (excluding starting positions)
    visited_count = sum(sum(1 for cell in row if cell) for row in visited)
    return visited_count - len(start_positions)
