def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)
    if n == 0:
        return []

    # Initialize result as identity matrix
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1 % mod

    def multiply(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        n = len(a)
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % mod
        return res

    def matrix_pow(mat: list[list[int]], power: int) -> list[list[int]]:
        current = [row.copy() for row in mat]
        res = [[0] * n for _ in range(n)]
        for i in range(n):
            res[i][i] = 1 % mod

        while power > 0:
            if power % 2 == 1:
                res = multiply(res, current)
            current = multiply(current, current)
            power //= 2
        return res

    return matrix_pow(matrix, exp)
