def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    # Reduce matrix entries modulo mod initially
    reduced_matrix = [[matrix[i][j] % mod for j in range(n)] for i in range(n)]

    # Identity matrix modulo mod
    def identity(n, mod):
        return [[0] * n for _ in range(n)] if mod == 1 else [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    result = identity(n, mod)

    while exp > 0:
        if exp % 2 == 1:
            # Multiply result by reduced_matrix modulo mod
