import re

def tidy_punctuation(text: str) -> str:
    # Step 1: Replace all whitespace sequences with single space and strip leading/trailing spaces
    text = re.sub(r'\s+', ' ', text).strip()

    # Step 2: Remove spaces before punctuation marks
    text = re.sub(r'\s*([,.;:!?])', r'\1', text)

    # Step 3: Add single space after punctuation marks if followed by a letter
    text = re.sub(r'([,.;:!?])(\w)', r'\1 \2', text)

    # Step 4: Capitalize first letter and letters after .!? followed by space
    words = text.split(' ')
    if words:
        words[0] = words[0].capitalize()
        for i in range(1, len(words)):
            if words[i-1].endswith(('.', '!', '?')):
                words[i] = words[i].capitalize()

    return ' '.join(words)

