def identifier_to_snake(name: str) -> str:
    if not re.search(r'[a-zA-Z0-9]', name):
        return ""

    # Split on underscores, hyphens, and camelCase/digit transitions
    parts = re.split(r'([A-Z][a-z]+|[A-Z]+?|[a-z]+|[0-9]+)', name)
    parts = [p for p in parts if p]  # Remove empty strings

    # Process camelCase and PascalCase splits
    result = []
    for part in parts:
        if part.isupper() and len(part) > 1:
            # Split consecutive uppercase letters (e.g., HTTPRequest -> HTTP, Request)
            sub_parts = re.findall(r'[A-Z]?[a-z]+|[A-Z]+?', part)
            for sub_part in sub_parts:
                if sub_part:
                    result.append(sub_part.lower())
        elif part.isupper() and len(part) == 1:
            # Single uppercase letter (e.g., 'A' in 'XMLParser' -> 'XML', 'Parser')
            result.append(part.lower())
        else:
            result.append(part.lower())

    # Join with underscores and handle consecutive underscores
    return '_'.join(result)
