    if not name:
        return ""

    # Replace hyphens with underscores and split into words
    parts = re.split(r'([A-Z][a-z]+|[A-Z]?[a-z0-9]+|[0-9]+)', name.replace('-', '_'))

    # Filter out empty strings and join with underscores
    words = [part.lower() for part in parts if part and part != '_']

    # Handle cases where camelCase or PascalCase might need splitting
    result = []
    for word in words:
        if re.match(r'^[A-Z][a-z]+$', word):
            result.append(word.lower())
        elif re.match(r'^[A-Z]?[a-z0-9]+$', word):
            result.append(word)
        elif re.match(r'^[0-9]+$', word):
            result.append(word)

    # Reprocess to handle camelCase/PascalCase splits
    final_words = []
    for i, word in enumerate(result):
        if i > 0 and word[0].isupper() and result[i-1][-1].islower():
            final_words.append(result[i-1])
            final_words.append(word.lower())
        else:
            final_words.append(word)

    # Handle cases like 'HTTPRequest' -> 'http_request'
    corrected_words = []
    for word in final_words:
        if word.isupper() and len(word) > 1:
            corrected_words.append(word.lower())
        else:
            corrected_words.append(word)

    return '_'.join(corrected_words)

