def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end or min_len <= 0:
        return []

    # Filter and sort busy intervals within the day
    busy_in_day = [interval for interval in busy if interval[0] < day_end and interval[1] > day_start]
    busy_in_day.sort()

    # Merge overlapping or touching intervals
    merged = []
    for interval in busy_in_day:
        if not merged:
            merged.append(interval)
        else:
            last_start, last_end = merged[-1]
            current_start, current_end = interval
            if current_start <= last_end:
                # Overlapping or touching, merge them
                new_start = min(last_start, current_start)
                new_end = max(last_end, current_end)
                merged[-1] = (new_start, new_end)
            else:
                merged.append(interval)

    # Generate free slots between busy intervals and day boundaries
    free_slots = []
    prev_end = day_start
    for start, end in merged:
        if start > prev_end and (start - prev_end) >= min_len:
            free_slots.append((prev_end, start))
        prev_end = max(prev_end, end)

    # Check the end of the day
    if prev_end < day_end and (day_end - prev_end) >= min_len:
        free_slots.append((prev_end, day_end))

