def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order, then by original order for ties
    sorted_jobs = sorted(jobs, key=lambda x: (-x[2], jobs.index(x)))
    available_slots = [False] * max(job[1] for job in jobs) if jobs else []

    scheduled = []
    for name, deadline, _ in sorted_jobs:
        # Find the latest available slot <= deadline
        for slot in range(deadline, 0, -1):
            if not available_slots[slot - 1]:
                available_slots[slot - 1] = True
                scheduled.append(name)
                break

    return scheduled

