def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Check for invalid sizes
    for size in sizes:
        if size <= 0 or size > capacity:
            raise ValueError("All items must have positive size and not exceed capacity")

    # Sort sizes in descending order
    sorted_sizes = sorted(sizes, reverse=True)

    bins = []

    for size in sorted_sizes:
        placed = False
        for bin_items in bins:
            if sum(bin_items) + size <= capacity:
                bin_items.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
