def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    blocked_set = {(x, y) for x, y in blocked}
    count = 0

    def backtrack(row, cols, diag1, diag2):
        nonlocal count
        if row == n:
            count += 1
            return
        for col in range(n):
            if col in cols or (row - col) in diag1 or (row + col) in diag2 or (row, col) in blocked_set:
                continue
            backtrack(row + 1, cols | {col}, diag1 | {row - col}, diag2 | {row + col})

    backtrack(0, set(), set(), set())
    return count
