def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    result_balances = balances.copy()
    failed_ops = []
    for op in ops:
        try:
            action, account, amount = op
            if action == 'deposit':
                result_balances[account] += amount
            elif action == 'withdraw':
                if result_balances[account] >= amount:
                    result_balances[account] -= amount
                else:
                    failed_ops.append(amount)
            else:
                failed_ops.append(amount)
        except (KeyError, ValueError):
            failed_ops.append(amount)
    return (result_balances, failed_ops)
