                stock[item] -= quantity
            else:
                waiting[item].append((item, quantity))

    # Prepare the output
    final_stock = {k: v for k, v in stock.items() if v > 0}
    final_waiting = [(item, qty) for item in waiting for qty in waiting[item]]

    return (final_stock, final_waiting)
