def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    waiting_queues = {}

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] = stock.get(item, 0) + quantity
            if item in waiting_queues:
                current_queue = waiting_queues[item]
                del waiting_queues[item]
                for (wait_item, wait_qty) in current_queue:
                    if stock[wait_item] >= wait_qty:
                        stock[wait_item] -= wait_qty
                    else:
                        waiting_queues[wait_item] = current_queue
                        break
                else:
                    waiting.extend(current_queue)
        elif kind == 'order':
            if item not in stock or stock[item] >= quantity:
                stock[item] = stock.get(item, 0) - quantity
            else:
                if item not in waiting_queues:
                    waiting_queues[item] = []
                waiting_queues[item].append((item, quantity))

    for item in waiting_queues:
        waiting.extend(waiting_queues[item])

    return (stock, waiting)
