def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or (number == '-' and len(number) == 1):
        raise ValueError("Invalid input number")

    if number[0] == '-':
        is_negative = True
        num_str = number[1:]
    else:
        is_negative = False
        num_str = number

    if not num_str:
        raise ValueError("Invalid input number")

    # Validate input characters
    for c in num_str:
        if c.isdigit():
            digit = int(c)
        else:
            digit = ord(c.lower()) - ord('a') + 10
        if digit >= from_base:
            raise ValueError(f"Invalid digit '{c}' for base {from_base}")

    # Convert to decimal
    decimal_value = 0
    for c in num_str:
        if c.isdigit():
            digit = int(c)
        else:
            digit = ord(c.lower()) - ord('a') + 10
        decimal_value = decimal_value * from_base + digit

    # Handle zero case
    if decimal_value == 0:
        return "0"

    # Convert from decimal to target base
    if is_negative:
        decimal_value = -decimal_value

    if decimal_value == 0:
        return "0"

    digits = []
    abs_value = abs(decimal_value)
    while abs_value > 0:
        remainder = abs_value % to_base
        if remainder < 10:
