def count_set_bits_range(lo: int, hi: int) -> int:
    def count_set_bits_up_to(n: int) -> int:
        if n == 0:
            return 0
        count = 0
        power = 1
        while power <= n:
            next_power = power << 1
            half_power = power >> 1
            full_cycles = (n + 1) // next_power
            count += full_cycles * power
            remainder = (n + 1) % next_power
            count += max(0, remainder - half_power)
            power = next_power
        return count

    if lo > hi:
        return 0
    return count_set_bits_up_to(hi) - count_set_bits_up_to(lo - 1)
