def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    output = []
    pc = 0  # program counter
    labels = {}
    label_counter = 0

    # First pass: resolve labels
    for line in program:
        line = line.strip()
        if line and not line.startswith('#'):
            parts = line.split()
            if parts and parts[0] == 'label':
                if len(parts) < 2:
                    return None
                labels[parts[1]] = label_counter
            label_counter += 1

    # Second pass: execute program
    pc = 0
    stack = []
    output = []
    while pc < len(program):
        line = program[pc].strip()
        if not line or line.startswith('#'):
            pc += 1
            continue

        parts = line.split()
        if not parts:
            pc += 1
            continue

        cmd = parts[0]

        if cmd == 'push':
            if len(parts) < 2:
                return None
            try:
                stack.append(int(parts[1]))
            except ValueError:
                return None
        elif cmd == 'pop':
            if not stack:
                return None
            stack.pop()
        elif cmd == 'dup':
            if not stack:
                return None
            stack.append(stack[-1])
        elif cmd == 'swap':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif cmd == 'add':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b)
        elif cmd == 'sub':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif cmd == 'mul':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(a * b)
        elif cmd == 'div':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            if a == 0:
                return None
            stack.append(b // a)
        elif cmd == 'mod':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            if a == 0:
                return None
            stack.append(b % a)
        elif cmd == 'print':
            if not stack:
                return None
            output.append(stack[-1])
        elif cmd == 'label':
            pass  # labels are resolved in first pass
        elif cmd == 'jmp':
            if len(parts) < 2:
                return None
            target = parts[1]
            if target in labels:
                pc = labels[target]
                continue
            else:
                return None
        elif cmd == 'jz':
            if len(parts) < 2 or not stack:
                return None
            target = parts[1]
            if stack[-1] == 0:
                if target in labels:
                    pc = labels[target]
                    continue
                else:
                    return None
        elif cmd == 'halt':
            return output
        else:
            return None

        pc += 1

    return output if output else None
