from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, can_break):
        queue = deque()
        queue.append((start[0], start[1], can_break))
        visited = {}
        visited[(start[0], start[1], can_break)] = 0

        while queue:
            x, y, break_used = queue.popleft()
            if (x, y) == end:
                return visited[(x, y, break_used)]

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols:
                    if grid[nx][ny] == '#':
                        if not break_used:
                            if (nx, ny, True) not in visited:
                                visited[(nx, ny, True)] = visited[(x, y, break_used)] + 1
                                queue.append((nx, ny, True))
                    else:
                        if (nx, ny, break_used) not in visited:
                            visited[(nx, ny, break_used)] = visited[(x, y, break_used)] + 1
                            queue.append((nx, ny, break_used))
        return -1

    result = bfs(start, False)
    return result
