def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    new_grid = [row.copy() for row in grid]
    changed = True

    while changed:
        changed = False
        topple_coords = []

        for r in range(rows):
            for c in range(cols):
                if new_grid[r][c] >= 4:
                    topple_coords.append((r, c))

        for r, c in topple_coords:
            new_grid[r][c] -= 4
            changed = True

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_grid[nr][nc] += 1

    return new_grid
