from pathlib import Path

def make_tar(directory: str, archive_path: str) -> str:
    # Validate inputs
    directory_path = Path(directory).resolve()
    archive_path = Path(archive_path).resolve()

    if not directory_path.is_dir():
        raise NotADirectoryError(f"Directory does not exist: {directory}")
    if archive_path.parent != archive_path.parent.resolve():
        raise ValueError("archive_path must be an absolute path or a path relative to the current directory")
    if archive_path.parent != directory_path.parent:
        raise ValueError("archive_path must not be inside the directory being archived")

    # Create tar archive
    try:
        subprocess.run(
            ["tar", "-cf", str(archive_path), str(directory_path)],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to create tar archive: {e.stderr.decode()}") from e

    return str(archive_path)

