import os
from urllib.parse import unquote

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # URL decode and normalize the path
    decoded_path = unquote(request_path)
    if not decoded_path.startswith('/'):
        return 404, b"Not Found"

    # Remove leading/trailing slashes and split into components
    path_components = decoded_path.strip('/').split('/')

    # Handle root case
    if not path_components:
        target_file = os.path.join(web_root, 'index.html')
    else:
        # Join components to form the relative path
        target_file = os.path.join(web_root, *path_components)

        # If path ends with '/', try to serve index.html
        if decoded_path.endswith('/'):
            target_file = os.path.join(target_file, 'index.html')

    # Security checks
    if not os.path.abspath(target_file).startswith(os.path.abspath(web_root) + os.sep):
        return 404, b"Not Found"

    # Check if file exists and is accessible
    if os.path.isfile(target_file):
        try:
            with open(target_file, 'rb') as f:
                return 200, f.read()
        except (IOError, OSError):
            return 404, b"Not Found"
    return 404, b"Not Found"
