    # Replace x with its value and validate the formula
    formula = formula.replace('x', str(x))

    # Validate the formula contains only allowed characters and functions
    if not re.fullmatch(r'^[\d+\-*/().xabcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\s]+$', formula):
        raise ValueError("Invalid characters in formula")

    # Replace allowed functions with their math equivalents
    formula = formula.replace('sqrt', 'math.sqrt')
    formula = formula.replace('abs', 'math.fabs')
    formula = formula.replace('sin', 'math.sin')
    formula = formula.replace('cos', 'math.cos')

    # Check for invalid function calls
    if 'sqrt(' in formula and not re.fullmatch(r'.*sqrt\([^)]+\)', formula):
        raise ValueError("Invalid sqrt function call")
    if 'abs(' in formula and not re.fullmatch(r'.*abs\([^)]+\)', formula):
        raise ValueError("Invalid abs function call")
    if 'sin(' in formula and not re.fullmatch(r'.*sin\([^)]+\)', formula):
        raise ValueError("Invalid sin function call")
    if 'cos(' in formula and not re.fullmatch(r'.*cos\([^)]+\)', formula):
        raise ValueError("Invalid cos function call")

    # Check for invalid function names
    if re.search(r'\b([a-zA-Z]+)\s*\(', formula):
        match = re.search(r'\b([a-zA-Z]+)\s*\(', formula)
        func_name = match.group(1)
        if func_name not in ['sqrt', 'abs', 'sin', 'cos']:
