import operator
import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Supported operators mapping
    ops = {
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.And: operator.and_,
        ast.Or: operator.or_,
        ast.Not: operator.not_,
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.USub: operator.neg,
    }

    # Parse the expression into AST
    try:
        node = ast.parse(expression, mode='eval').body
    except (SyntaxError, ValueError) as e:
        raise ValueError(f"Invalid expression: {e}")

    # Validate all names in the expression are keys in record
    for n in ast.walk(node):
        if isinstance(n, ast.Name) and not isinstance(n.ctx, ast.Load):
            continue  # Skip store contexts (not relevant here)
        if isinstance(n, ast.Name) and n.id not in record:
            raise ValueError(f"Unknown key: {n.id}")

    # Create a safe evaluation environment
    env = {**record, 'True': True, 'False': False}

    def _eval(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Str):
            return node.s
        elif isinstance(node, ast.Name):
            return env[node.id]
        elif isinstance(node, ast.Constant):  # Python 3.8+ support
            return node.value
        elif isinstance(node, ast.UnaryOp):
            return ops[type(node.op)](_eval(node.operand))
        elif isinstance(node, ast.BinOp):
            return ops[type(node.op)](_eval(node.left), _eval(node.right))
        elif isinstance(node, ast.Compare):
            left = _eval(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = _eval(comparator)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        elif isinstance(node, ast.BoolOp):
            return ops[type(node.op)]([_eval(value) for value in node.values])
        elif isinstance(node, ast.IfExp):
            return _eval(node.body) if _eval(node.test) else _eval(node.orelse)
        else:
            raise ValueError(f"Unsupported expression type: {type(node).__name__}")

    try:
        result = _eval(node)
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

    if not isinstance(result, bool):
        raise ValueError("Expression must evaluate to a boolean")

    return result
