    local, domain = s.split('@', 1)
    if '..' in local or '--' in local or '__' in local:
        return False

    domain_parts = domain.split('.')
    if len(domain_parts) < 2:
        return False

    for part in domain_parts[:-1]:
        if not part.isalnum():
            return False

    if not domain_parts[-1].isalpha() or len(domain_parts[-1]) < 2:
        return False

