def create_work_dir() -> str:
    """Create a secure, temporary working directory and return its path.

    The directory is guaranteed to be empty and will be automatically
    cleaned up when the program exits, unless explicitly removed by the caller.
    """
    try:
        # Create a temporary directory with a secure random name
        work_dir = tempfile.mkdtemp(prefix="work_", dir=os.getcwd())

        # Verify the directory exists and is empty
        if not os.path.exists(work_dir):
            raise RuntimeError("Failed to create directory")
        if os.listdir(work_dir):
            raise RuntimeError("Directory is not empty")

        # Register cleanup on program exit (unless removed by caller)
        def cleanup():
            try:
                shutil.rmtree(work_dir, ignore_errors=True)
            except OSError:
                pass

        import atexit
        atexit.register(cleanup)

        return work_dir

    except Exception as e:
        # Attempt cleanup if something went wrong
        if 'work_dir' in locals():
            try:
                shutil.rmtree(work_dir, ignore_errors=True)
            except OSError:
                pass
        raise RuntimeError(f"Failed to create secure work directory: {str(e)}")
