from typing import Dict, Any

def render_greeting_card(template: str, recipient: str, sender: str) -> str:
    env = Environment(undefined=StrictUndefined)
    env.filters['upper'] = lambda s: s.upper()
    env.filters['lower'] = lambda s: s.lower()
    env.filters['capitalize'] = lambda s: s.capitalize()

    def render_var(var_name: str) -> str:
        if var_name == 'recipient':
            return recipient
        elif var_name == 'sender':
            return sender
        return ''

    def render_node(node):
        if node.type == 'Variable':
            var_name = node.name
            if '|' in var_name:
                var_name, filter_name = var_name.split('|', 1)
                value = render_var(var_name.strip())
                if filter_name.strip() in env.filters:
                    return env.filters[filter_name.strip()](value)
                return value
            else:
                return render_var(var_name)
        elif node.type == 'String':
            return node.value
        return ''

    def render_template(template_str):
        from jinja2.nodes import NodeVisitor
        class CustomVisitor(NodeVisitor):
            def visit_Block(self, node):
                return ''.join(self.visit(node.body))

            def visit_Output(self, node):
                return ''.join(self.visit(node.nodes))

            def visit_String(self, node):
                return node.value

            def visit_Variable(self, node):
                return render_node(node)

        parsed = env.parse(template_str)
        visitor = CustomVisitor()
        visitor.visit(parsed)
        return visitor.result

    return render_template(template)
