def log_requests(log_path: str, requests: list[dict]) -> int:
    import os
    from pathlib import Path

    # Validate input
    if not isinstance(requests, list):
        raise TypeError("requests must be a list of dictionaries")

    required_keys = {'timestamp', 'ip', 'path', 'user_agent'}
    for request in requests:
        if not isinstance(request, dict) or not required_keys.issubset(request.keys()):
            raise ValueError("Each request must be a dict with keys: timestamp, ip, path, user_agent")

    # Prepare data for writing
    lines = []
    for request in requests:
        # Escape quotes in path and user_agent by doubling them
        escaped_path = request['path'].replace('"', '\\"')
        escaped_user_agent = request['user_agent'].replace('"', '\\"')

        line = f'{request["timestamp"]} {request["ip"]} "{escaped_path}" "{escaped_user_agent}"\n'
        lines.append(line)

    # Write to file securely
    try:
        with open(log_path, 'a', encoding='utf-8') as f:
            f.writelines(lines)
        return len(lines)
    except IOError as e:
        raise IOError(f"Failed to write to log file at {log_path}: {e}")
