import os

def read_gzip_text(path: str) -> str:
    """Read a gzip-compressed text file and return its decompressed content as a UTF-8 string."""
    if not os.path.exists(path):
        raise FileNotFoundError(f"The file {path} does not exist.")

    if not os.path.isfile(path):
        raise IsADirectoryError(f"{path} is a directory, not a file.")

    try:
        with gzip.open(path, mode='rt', encoding='utf-8') as file:
            return file.read()
    except UnicodeDecodeError as e:
        raise ValueError(f"Failed to decode file as UTF-8: {e}")
    except gzip.BadGzipFile:
        raise ValueError(f"The file {path} is not a valid gzip file.")
    except PermissionError:
        raise PermissionError(f"Permission denied when trying to read {path}.")
    except OSError as e:
        raise OSError(f"Error reading file {path}: {e}")
