        try:
            # Prevent directory traversal and path manipulation attacks
            if not member or member.startswith('/') or '..' in member or member.endswith('/'):
                raise KeyError(f"Invalid member name: {member}")

            # Normalize path to prevent path traversal
            member_path = Path(member).resolve()
            if str(member_path) != member:
                raise KeyError(f"Invalid member name: {member}")

            if member not in zf.namelist():
                raise KeyError(f"Member not found: {member}")

            content = zf.read(member)
            return content.decode('utf-8')

        except zipfile.BadZipFile:
