from io import StringIO

def count_items(xml_text: str) -> int:
    try:
        # Parse XML securely by preventing XXE and other vulnerabilities
        parser = ET.XMLParser(resolve_entities=False, strip_cdata=False)
        root = ET.parse(StringIO(xml_text), parser=parser).getroot()
    except ET.ParseError:
        return 0

    def count_items_recursive(element):
        count = 0
        if element.tag == 'item':
            count += 1
        for child in element:
            count += count_items_recursive(child)
        return count

    return count_items_recursive(root)
