def read_title(xml_text: str) -> str:
    try:
        root = ET.fromstring(xml_text)
        # Handle cases where title might be in different tags (e.g., <title>, <book><title>, etc.)
        title_element = root.find('.//title')
        if title_element is not None:
            return title_element.text.strip() if title_element.text else ""
        # Fallback for common XML structures like HTML or other formats
        title_element = root.find('.//head/title') if root.tag != 'title' else None
        if title_element is not None and title_element.text:
            return title_element.text.strip()
        return ""
    except ParseError:
        return ""
