def get_users_by_ids(conn, ids: list) -> list[tuple]:
    if not ids:
        return []

    # Convert all ids to integers and remove duplicates while preserving order
    unique_ids = []
    seen = set()
    for id_ in ids:
        try:
            int_id = int(id_)
            if int_id not in seen:
                seen.add(int_id)
                unique_ids.append(int_id)
        except ValueError:
            continue

    # Fetch users in order of unique_ids
    query = "SELECT id, username FROM users WHERE id IN ({}) ORDER BY id ASC".format(
        ",".join("?" * len(unique_ids))
    )
    cursor = conn.cursor()
    cursor.execute(query, unique_ids)
    return cursor.fetchall()
