def compute_mode(nums: list[int]) -> list[int]:
    if not nums:
        return []

    frequency = defaultdict(int)
    for num in nums:
        frequency[num] += 1

    max_freq = max(frequency.values())
    modes = [num for num, count in frequency.items() if count == max_freq]

    return sorted(modes)
