def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    if not intervals:
        return 0

    # Sort intervals by start time
    intervals.sort()
    count = 0
    n = len(intervals)

    for i in range(n):
        for j in range(i + 1, n):
            a_start, a_end = intervals[i]
            b_start, b_end = intervals[j]
            # Check if intervals overlap (including touching at endpoints)
            if a_start <= b_end and b_start <= a_end:
                count += 1

    return count

