def count_inversions(nums: list[int]) -> int:
    def merge_sort_and_count(nums, left, right):
        if left >= right:
            return 0

        mid = (left + right) // 2
        inv_count = merge_sort_and_count(nums, left, mid) + merge_sort_and_count(nums, mid + 1, right)

        i = left
        j = mid + 1
        temp = []

        while i <= mid and j <= right:
            if nums[i] <= nums[j]:
                temp.append(nums[i])
                i += 1
            else:
                temp.append(nums[j])
                inv_count += (mid - i + 1)
                j += 1

        while i <= mid:
            temp.append(nums[i])
            i += 1

        while j <= right:
            temp.append(nums[j])
            j += 1

        for k in range(len(temp)):
            nums[left + k] = temp[k]

        return inv_count

    return merge_sort_and_count(nums, 0, len(nums) - 1) if nums else 0
