def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(remaining):
        if remaining == 0:
            return 0
        if remaining < 0:
            return float('inf')
        min_coins = float('inf')
        for i in range(len(coins)):
            if limits[i] > 0:
                for k in range(1, limits[i] + 1):
                    res = dp(remaining - k * coins[i])
                    if res != float('inf'):
                        min_coins = min(min_coins, res + k)
        return min_coins if min_coins != float('inf') else -1

    result = dp(target)
    return result if result != float('inf') else -1
