def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from functools import lru_cache

    n = len(coins)
    if target == 0:
        return 0

    @lru_cache(maxsize=None)
    def dp(remaining: int, index: int) -> int:
        if remaining == 0:
            return 0
        if index >= n or remaining < 0:
            return float('inf')

        # Option 1: Don't use this coin type at all
        res = dp(remaining, index + 1)

        # Option 2: Use this coin type up to its limit
        for used in range(1, limits[index] + 1):
            current_coin = coins[index] * used
            if current_coin > remaining:
                break
            res = min(res, dp(remaining - current_coin, index + 1) + used)

        return res if res != float('inf') else -1

    result = dp(target, 0)
    return result if result != float('inf') else -1
