from collections import defaultdict

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    heap = []
    heapq.heappush(heap, (0, start, [start]))
    visited = {}

    while heap:
        current_cost, current_node, path = heapq.heappop(heap)

        if current_node in visited:
            continue
        visited[current_node] = (current_cost, path)

        if current_node == goal:
            return (current_cost, path)

        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                new_cost = current_cost + weight
                new_path = path + [neighbor]
                heapq.heappush(heap, (new_cost, neighbor, new_path))

    return None
