from collections import deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    # Build adjacency list and in-degree count
    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    for a, b in pairs:
        if a == b:
            return []  # Cycle detected
        if b not in adj[a]:
            adj[a].append(b)
            in_degree[b] += 1

    # Initialize queue with nodes having zero in-degree
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        # Sort to ensure lexicographical order
        queue = deque(sorted(queue))
        u = queue.popleft()
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return result if len(result) == n else []
