from collections import deque, defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS to find shortest distance
    distance = [-1] * n
    parent = defaultdict(list)
    q = deque()
    q.append(source)
    distance[source] = 0

    while q:
        u = q.popleft()
        for v in adj[u]:
            if distance[v] == -1:
                distance[v] = distance[u] + 1
                parent[v] = [u]
                q.append(v)
            elif distance[v] == distance[u] + 1:
                parent[v].append(u)

    if distance[target] == -1:
        return 0

    # DFS to count paths
    def dfs(node):
        if node == source:
            return 1
        return sum(dfs(p) for p in parent[node])

    return dfs(target)
