import re

def parse_csv(text: str) -> list[list[str]]:
    if not text.strip():
        return []

    # This regex handles quoted fields (with escaped quotes) and unquoted fields
    pattern = r'(?:^|,)(?:"(?:""|[^"])*"|[^,]*)'
    fields = re.findall(pattern, text)

    # Split fields into records, handling empty lines
    records = []
    current_record = []
    for field in fields:
        if field == '':
            if current_record:
                records.append(current_record)
                current_record = []
        else:
            # Remove surrounding quotes if present
            if field.startswith('"') and field.endswith('"'):
                field = field[1:-1].replace('""', '"')
            current_record.append(field)

    # Add the last record if it exists
    if current_record:
        records.append(current_record)

    return records
