    import re

    def parse_expression(s):
        tokens = re.findall(r'(\d+|[-+*/^()])', s.replace(' ', ''))
        values, ops = [], []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                ops.append(token)
                i += 1
                while tokens[i] != ')':
                    i += 1
                sub_expr = ''.join(tokens[i - len(values):i + 1])
                values.append(parse_expression(sub_expr))
                values.pop(0)
                ops.pop(0)
                i += 1
            else:
                ops.append(token)
            i += 1
        return evaluate(values, ops)

    def evaluate(values, ops):
        def apply_op(a, b, op):
            if op == '+': return a + b
            if op == '-': return a - b
            if op == '*': return a * b
            if op == '/':
                if b == 0: raise ZeroDivisionError
                return a // b
            if op == '^': return a ** b

        def precedence(op):
            if op == '^': return 4
            if op in ('*', '/'): return 3
            if op in ('+', '-'): return 2
            return 0

        def apply_unary_minus():
            nonlocal values, ops
            if not ops:
                return
            op = ops.pop()
            if op == '-':
                val = values.pop()
                values.append(-val)
            else:
                ops.append(op)

        while '(' in ops:
            pos = ops.index('(')
            ops.pop(pos)
            values.pop(pos)

        while ops:
            op = ops.pop(0)
            if op == '-':
                apply_unary_minus()
                continue
            if op == '^':
                while ops and precedence(ops[0]) >= precedence(op):
                    ops.insert(0, op)
