        tokens = re.findall(r'(\d+|[-+*/^()])', s.replace(' ', ''))
        values, ops = [], []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                values.append(int(token))
            elif token == '(':
                j = i + 1
                balance = 1
                while j < len(tokens) and balance != 0:
                    if tokens[j] == '(':
                        balance += 1
                    elif tokens[j] == ')':
                        balance -= 1
                    j += 1
                sub_expr = ''.join(tokens[i+1:j-1])
                values.append(parse_expression(sub_expr))
                i = j - 1
            elif token == '-':
                if i == 0 or tokens[i-1] in '+-*/(':
                    values.append(0)
                    ops.append('u-')
                else:
                    ops.append(token)
            else:
                ops.append(token)
            i += 1
        return values, ops

    def evaluate(values, ops):
        if not ops:
            return values[0]

        values = values.copy()
        ops = ops.copy()

        # Handle exponentiation (right-associative)
        i = len(ops) - 1
        while i >= 0:
            if ops[i] == '^':
                right = values.pop()
                left = values.pop()
                values.append(left ** right)
                ops.pop(i)
            i -= 1

        # Handle unary minus
        i = 0
        while i < len(ops):
            if ops[i] == 'u-':
                values[i] = -values[i]
                ops.pop(i)
            else:
                i += 1

        # Handle * and /
        i = 0
        while i < len(ops):
            if ops[i] in '*/':
                left = values[i]
                right = values[i+1]
                if ops[i] == '*':
                    values[i] = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    values[i] = left // right
                values.pop(i+1)
                ops.pop(i)
            else:
                i += 1

        # Handle + and -
        result = values[0]
        for i in range(len(ops)):
            if ops[i] == '+':
                result += values[i+1]
            elif ops[i] == '-':
                result -= values[i+1]
        return result

    values, ops = parse_expression(expr)
    return evaluate(values, ops)
