def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    formatted_rows = []
    for row in rows:
        formatted_cells = []
        for i, (cell, align) in enumerate(zip(row, aligns)):
            width = col_widths[i]
            padding = width - len(cell)

            if align == 'l':
                formatted_cell = cell.ljust(width)
            elif align == 'r':
                formatted_cell = cell.rjust(width)
            elif align == 'c':
                left_pad = padding // 2
                right_pad = padding - left_pad
                formatted_cell = cell.center(width)
            else:
                raise ValueError(f"Invalid alignment character '{align}'")

            formatted_cells.append(formatted_cell)

        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
