def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix:
        return []

    n = len(matrix)
    result = [row[:] for row in matrix]
    rings = (n + 1) // 2

    for ring in range(rings):
        if ring == rings - 1 and n % 2 == 1:
            break  # Middle element in odd-sized matrix

        top = ring
        bottom = n - 1 - ring
        left = ring
        right = n - 1 - ring

        # Extract the ring elements
        ring_elements = []

        # Top row (left to right)
        for i in range(left, right):
            ring_elements.append(result[top][i])

        # Right column (top to bottom)
        for i in range(top, bottom):
            ring_elements.append(result[i][right])

        # Bottom row (right to left)
        if top != bottom:
            for i in range(right, left, -1):
                ring_elements.append(result[bottom][i])

        # Left column (bottom to top)
        if left != right:
            for i in range(bottom, top, -1):
                ring_elements.append(result[i][left])

        if not ring_elements:
            continue

        ring_length = len(ring_elements)
        k = k % ring_length if ring_length != 0 else 0

        # Rotate the ring elements
        rotated_elements = ring_elements[-k:] + ring_elements[:-k]

        # Place the rotated elements back
        idx = 0

        # Top row (left to right)
        for i in range(left, right):
            result[top][i] = rotated_elements[idx]
            idx += 1

        # Right column (top to bottom)
        for i in range(top, bottom):
            result[i][right] = rotated_elements[idx]
            idx += 1

        # Bottom row (right to left)
        if top != bottom:
            for i in range(right, left, -1):
                result[bottom][i] = rotated_elements[idx]
                idx += 1

        # Left column (bottom to top)
        if left != right:
            for i in range(bottom, top, -1):
                result[i][left] = rotated_elements[idx]
                idx += 1

    return result

