def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end or min_len <= 0:
        return []

    # Filter and normalize busy intervals
    busy_intervals = []
    for start, end in busy:
        if start < end:
            busy_intervals.append((max(start, day_start), min(end, day_end)))

    if not busy_intervals:
        return [(day_start, day_end)] if day_end - day_start >= min_len else []

    # Sort intervals by start time
    busy_intervals.sort()

    # Merge overlapping intervals
    merged = []
    for interval in busy_intervals:
        if not merged:
            merged.append(interval)
        else:
            last_start, last_end = merged[-1]
            current_start, current_end = interval
            if current_start <= last_end:
                # Overlapping or adjacent intervals, merge them
                new_start = last_start
                new_end = max(last_end, current_end)
                merged[-1] = (new_start, new_end)
            else:
                merged.append(interval)

    # Find free slots between busy intervals and day boundaries
    free_slots = []
    prev_end = day_start

    for start, end in merged:
        if start - prev_end >= min_len:
            free_slots.append((prev_end, start))
        prev_end = end

    # Check the last free slot after the last busy interval
    if day_end - prev_end >= min_len:
        free_slots.append((prev_end, day_end))

    return free_slots
