def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    # Check for items larger than capacity
    for size in sizes:
        if size > capacity:
            raise ValueError("Item size exceeds bin capacity")

    # Sort items in decreasing order
    sorted_sizes = sorted(sizes, reverse=True)

    bins = []

    for size in sorted_sizes:
        placed = False
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                placed = True
                break
        if not placed:
            bins.append([size])

    return bins
