            d1 = row - col
            d2 = row + col
            if col in cols or d1 in diag1 or d2 in diag2:
                continue
            backtrack(row + 1, cols | {col}, diag1 | {d1}, diag2 | {d2})

    backtrack(0, set(), set(), set())
    return count
