def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit descending, then by original order for ties
    sorted_jobs = sorted(jobs, key=lambda x: (-x[2], jobs.index(x)))

    # Use a min-heap to keep track of available slots
    import heapq
    available_slots = []
    scheduled = []

    for name, deadline, profit in sorted_jobs:
        if deadline < 1:
            continue
        # Push all slots up to the deadline into the heap
        for slot in range(1, deadline + 1):
            if slot not in scheduled:
                heapq.heappush(available_slots, slot)
        # Assign the largest available slot (using heap as a min-heap)
        if available_slots:
            slot = heapq.heappop(available_slots)
            scheduled.append(slot)
            scheduled.sort()  # Keep scheduled slots sorted for clarity

    # Create the result by mapping slots to job names in order
    # Since we need names in slot order, we need to track which job is in which slot
    # Reconstructing the schedule with names
    scheduled_jobs = [None] * max(scheduled) if scheduled else []
    job_to_slot = {}
    for name, deadline, profit in sorted_jobs:
        if deadline < 1:
            continue
        # Find the largest available slot <= deadline
        slot = None
        for s in range(deadline, 0, -1):
            if s not in scheduled:
                slot = s
                break
        if slot is not None:
            job_to_slot[slot] = name
            scheduled.append(slot)

    # Generate the result in slot order
    result = []
    for slot in range(1, max(scheduled) + 1):
        if slot in job_to_slot:
            result.append(job_to_slot[slot])

    return result

