        if kind == 'receive':
            stock[item] += quantity
            while waiting[item] and stock[item] >= waiting[item][0][1]:
                _, q = waiting[item].popleft()
                stock[item] -= q
                waiting_order.append((item, q))
        else:  # 'order'
            if stock[item] >= quantity:
                stock[item] -= quantity
                waiting_order.append((item, quantity))
            else:
                waiting[item].append((item, quantity))

    # Prepare the output waiting list in order of placement
    output_waiting = []
    for item in waiting:
