from collections import defaultdict, deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = defaultdict(deque)
    waiting_order = []  # To maintain order of pending orders across all items

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
            # Process pending orders for this item
            while waiting[item] and stock[item] >= waiting[item][0]:
                pending_qty = waiting[item].popleft()
                stock[item] -= pending_qty
        else:  # 'order'
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting[item].append(quantity)
                waiting_order.append((item, quantity))

    # Prepare the waiting list in the order they were placed
    waiting_list = [(item, qty) for item, qty in waiting_order if qty > 0]

    # Convert stock to a regular dict and include all items (even with 0 stock)
    all_items = set(stock.keys()).union({item for item, _ in waiting_order})
    stock_dict = {item: stock[item] for item in all_items}

    return (stock_dict, waiting_list)
