from collections import defaultdict, deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = defaultdict(deque)
    waiting_list = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
            # Fulfill waiting orders for this item
            while stock[item] > 0 and waiting[item]:
                order_item, order_qty = waiting[item].popleft()
                fulfill_qty = min(stock[item], order_qty)
                stock[item] -= fulfill_qty
                order_qty -= fulfill_qty
                if order_qty > 0:
                    waiting[item].appendleft((order_item, order_qty))
        else:  # kind == 'order'
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting[item].append((item, quantity))
                waiting_list.append((item, quantity))

    # Convert defaultdicts to regular dicts and lists
    stock_dict = dict(stock)
    # Ensure all items in waiting_list are included in stock_dict (even with 0 stock)
    for item, _ in waiting_list:
        if item not in stock_dict:
            stock_dict[item] = 0

    return (stock_dict, waiting_list)
