def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    steps = 0
    max_steps = 1000

    while ip < len(program):
        if steps >= max_steps:
            return None
        steps += 1

        instruction = program[ip].split()
        cmd = instruction[0]

        try:
            if cmd == 'PUSH':
                n = int(instruction[1])
                stack.append(n)
                ip += 1
            elif cmd == 'POP':
                if not stack:
                    return None
                stack.pop()
                ip += 1
            elif cmd == 'DUP':
                if not stack:
                    return None
                stack.append(stack[-1])
                ip += 1
            elif cmd == 'SWAP':
                if len(stack) < 2:
                    return None
                stack[-1], stack[-2] = stack[-2], stack[-1]
                ip += 1
            elif cmd == 'ADD':
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
                ip += 1
            elif cmd == 'SUB':
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
