def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36")

    if not number or (number == '-' and len(number) == 1):
        raise ValueError("Empty or invalid input")

    if number[0] == '-':
        is_negative = True
        num_str = number[1:]
    else:
        is_negative = False
        num_str = number

    if not num_str:
        raise ValueError("Empty input after sign")

    # Check for invalid characters
    for c in num_str:
        if c.isdigit():
            digit = int(c)
        else:
            digit = ord(c.lower()) - ord('a') + 10
        if digit >= from_base:
            raise ValueError(f"Invalid digit '{c}' for base {from_base}")

    # Convert to decimal
    decimal_value = 0
    for c in num_str:
        if c.isdigit():
            digit = int(c)
        else:
            digit = ord(c.lower()) - ord('a') + 10
        decimal_value = decimal_value * from_base + digit

    if decimal_value == 0:
        return '0'

    # Convert from decimal to target base
    digits = []
    n = decimal_value
    while n > 0:
        remainder = n % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        n = n // to_base

    result = ''.join(reversed(digits))
    return '-' + result if is_negative else result
