def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Invalid input")

    is_negative = number[0] == '-'
    if is_negative:
        number = number[1:]

    if not number:
        raise ValueError("Invalid input")

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    try:
        decimal_value = 0
        for char in number.lower():
            if char not in digits[:from_base]:
                raise ValueError("Invalid digit in input")
            decimal_value = decimal_value * from_base + digits.index(char)
    except ValueError:
        raise ValueError("Invalid digit in input")

    if decimal_value == 0:
        return '0'

    result = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result.append(digits[remainder])
        decimal_value = decimal_value // to_base

    result_str = ''.join(reversed(result))
    return '-' + result_str if is_negative else result_str
