from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start = end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS setup: (i, j, wall_break_used, steps)
    queue = deque()
    queue.append((start[0], start[1], False, 0))
    visited = {}
    visited[(start[0], start[1], False)] = True

    while queue:
        i, j, used_break, steps = queue.popleft()

        if (i, j) == end:
            return steps

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                if grid[ni][nj] == '#':
                    if not used_break:
                        if (ni, nj, True) not in visited:
                            visited[(ni, nj, True)] = True
                            queue.append((ni, nj, True, steps + 1))
                else:
                    if (ni, nj, used_break) not in visited:
                        visited[(ni, nj, used_break)] = True
                        queue.append((ni, nj, used_break, steps + 1))

    return -1
