        i, j, breaks_used, steps = queue.popleft()

        if (i, j) == end:
            return steps

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                if grid[ni][nj] == '#':
                    if breaks_used == 0:
                        if (ni, nj, 1) not in visited:
                            visited.add((ni, nj, 1))
                            queue.append((ni, nj, 1, steps + 1))
                else:
                    if (ni, nj, breaks_used) not in visited:
                        visited.add((ni, nj, breaks_used))
                        queue.append((ni, nj, breaks_used, steps + 1))

    return -1

