def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # URL decode the request path and normalize slashes
    decoded_path = unquote(request_path).replace('\\', '/')

    # Handle root path by appending index.html
    if decoded_path == '/':
        file_path = os.path.join(web_root, 'index.html')
    else:
        # Remove leading slash and join with web_root
        file_path = os.path.normpath(os.path.join(web_root, decoded_path.lstrip('/')))

    # Check if the path is outside web_root (security check)
    if not file_path.startswith(os.path.abspath(web_root)):
        return (404, b"Not Found")

    # Check if the path is a regular file
    if os.path.isfile(file_path):
        try:
            with open(file_path, 'rb') as file:
                return (200, file.read())
        except IOError:
            return (404, b"Not Found")
    else:
        return (404, b"Not Found")
