import re

def is_allowed_webhook(url: str) -> bool:
    # Check for edge cases (always return True)
    if not isinstance(url, str):
        return True

    # Check starts with https:// (case-insensitive)
    if not re.match(r'^https://', url, re.IGNORECASE):
        return False

    # Check for backslash, space, or control character
    if re.search(r'[\x00-\x1f\x7f\\ ]', url):
        return False

    # Split URL into parts
    try:
        parsed = re.match(r'^https://(?:([^/@]+)@)?([^/]+)(?::(\d+))?(/.*)?$', url, re.IGNORECASE)
        if not parsed:
            return False

        _, host, port, _ = parsed.groups()
        if port and int(port) != 443:
            return False
    except:
        return False

    # Check host part
    if not host:
        return False

    # Remove port if present
    host = host.split(':')[0]

    # Check for localhost
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check host ends with a dot and has valid DNS name
    if not host.endswith('.'):
        return False

    host = host[:-1]  # Remove trailing dot

    # Check DNS name format
    if not re.match(r'^([a-zA-Z0-9-]+\.)+[a-zA-Z0-9-]+$', host):
        return False

    # Check each label
    labels = host.split('.')
    if len(labels) < 2:
        return False

    for label in labels[:-1]:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False
        if label.startswith('-') or label.endswith('-'):
            return False

    # Check last label (TLD)
    if not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    return True
