import re

def is_public_ip(ip_str: str) -> bool:
    # Check if the string matches IPv4 or IPv6 standard text form
    ipv4_pattern = r'^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'
    ipv6_pattern = r'^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^(([0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{1,4})?::(([0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{1,4})?$|^::(ffff(:0{1,4}){0,1}:){0,1}((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$'

    if not (re.match(ipv4_pattern, ip_str) or re.match(ipv6_pattern, ip_str)):
        return False

    try:
        ip = ipaddress.ip_address(ip_str)
    except ValueError:
        return False

    # Handle IPv4-mapped IPv6 addresses
    if ip.version == 6 and ip.is_ipv4_mapped:
        ip = ipaddress.ip_address(ip.ipv4_mapped)

    # Check for public routable IP
    if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved or ip.is_unspecified:
        return False

    # Check for shared address space (100.64.0.0/10)
    if ip.version == 4 and ipaddress.ip_address('100.64.0.0') <= ip <= ipaddress.ip_address('100.127.255.255'):
        return False

    # Check for IPv4 broadcast address
    if ip.version == 4 and ip == ipaddress.ip_address('255.255.255.255'):
        return False

    return True

