import math
from collections import Counter

def token_entropy(tokens: list[str]) -> float:
    if not tokens:
        return 0.0

    total = len(tokens)
    freq = Counter(tokens)
    probabilities = [count / total for count in freq.values()]

    entropy = sum(-p * math.log2(p) for p in probabilities)
    return round(entropy, 3)

def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)

    if min_val == max_val:
        return [0.0 for _ in nums]

    normalized = [(x - min_val) / (max_val - min_val) for x in nums]
    return [round(x, 2) for x in normalized]

