def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    if not intervals:
        return 0

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    count = 0

    for i in range(len(sorted_intervals)):
        current_start, current_end = sorted_intervals[i]
        for j in range(i + 1, len(sorted_intervals)):
            other_start, other_end = sorted_intervals[j]
            # Check if intervals overlap (including touching at endpoints)
            if other_start <= current_end:
                count += 1
            else:
                # Early termination if no more overlaps are possible
                break
    return count
