def group_by_mod(nums: List[int], m: int) -> Dict[int, List[int]]:
    """Groups integers by their remainder when divided by m.

    Args:
        nums: List of integers to group.
        m: Modulus for grouping. Must be positive; otherwise, returns empty dict.

    Returns:
        Dictionary mapping remainders to lists of numbers with that remainder,
        preserving original order. Only remainders that occur are included.
    """
    if m <= 0:
        return {}

    result = {}
    for num in nums:
        remainder = num % m
        if remainder not in result:
            result[remainder] = []
        result[remainder].append(num)
    return result

