def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    from functools import lru_cache

    n = len(coins)
    if target == 0:
        return 0

    @lru_cache(maxsize=None)
    def dp(remaining, used):
        if remaining == 0:
            return 0
        if used == n:
            return float('inf')
        min_coins = float('inf')
        max_possible = min(limits[used], remaining // coins[used])
        for take in range(max_possible + 1):
            res = dp(remaining - take * coins[used], used + 1)
            if res != float('inf'):
                min_coins = min(min_coins, take + res)
        return min_coins if min_coins != float('inf') else -1

    result = dp(target, 0)
    return result if result != float('inf') else -1
