                inc[i] = inc[j] + 1

    # Compute decreasing subsequence lengths
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if nums[i] > nums[j] and dec[i] < dec[j] + 1:
                dec[i] = dec[j] + 1

    # Find the maximum bitonic length
    max_len = 0
    for i in range(n):
        current_len = inc[i] + dec[i] - 1
        if current_len > max_len:
            max_len = current_len

    return max_len

