def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    from collections import defaultdict

    # Build adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    bridges = []
    disc = [0] * n
    low = [0] * n
    time = 1
    visited = [False] * n

    def dfs(u, parent):
        nonlocal time
        visited[u] = True
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((min(u, v), max(u, v)))
            elif v != parent:
                low[u] = min(low[u], disc[v])

    for u in range(n):
        if not visited[u]:
            dfs(u, -1)

    bridges.sort()
    return bridges

