from collections import deque, defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS to find shortest distance
    distance = [-1] * n
    parent = [set() for _ in range(n)]
    queue = deque([source])
    distance[source] = 0

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if distance[v] == -1:
                distance[v] = distance[u] + 1
                parent[v].add(u)
                queue.append(v)
            elif distance[v] == distance[u] + 1:
                parent[v].add(u)

    if distance[target] == -1:
        return 0

    # DFS to count paths
    def dfs(u):
        if u == source:
            return 1
        return sum(dfs(p) for p in parent[u])

    return dfs(target)
