def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build adjacency list and remove duplicate edges
    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    # BFS to find shortest distance from source to all nodes
    distance = [-1] * n
    distance[source] = 0
    queue = deque([source])

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if distance[v] == -1:
                distance[v] = distance[u] + 1
                queue.append(v)

    if distance[target] == -1:
        return 0

    # DP to count shortest paths
    dp = [0] * n
    dp[source] = 1
    queue = deque([source])

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if distance[v] == distance[u] + 1:
                dp[v] += dp[u]
                queue.append(v)

    return dp[target]

