def parse_csv(text: str) -> list[list[str]]:
    if not text.strip():
        return []

    records = []
    current_record = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '"':
            # Parse quoted field
            field = []
            i += 1
            while i < n:
                if text[i] == '"':
                    if i + 1 < n and text[i+1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(text[i])
                    i += 1
            current_record.append(''.join(field))
        else:
            # Parse unquoted field
            field = []
            while i < n and text[i] not in {',', '\n'}:
                field.append(text[i])
                i += 1
            current_record.append(''.join(field))

        # Check if record is complete
        if i < n and text[i] == '\n':
            records.append(current_record)
            current_record = []
            i += 1
        elif i < n and text[i] == ',':
            i += 1
        else:
            break

    if current_record:
        records.append(current_record)

    return records
