            while tokens and tokens[0] == '^':
                tokens.pop(0)
                right = parse_unary_minus(tokens)
                if right < 0:
                    raise ValueError("Exponent must be non-negative")
                left = left ** right
            return left

        def parse_mul_div(tokens):
            left = parse_power(tokens)
            while tokens and tokens[0] in '*/':
                op = tokens.pop(0)
                right = parse_power(tokens)
                if op == '*':
                    left *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = int(left / right) if left >= 0 else -(-left // right)
            return left

