                val = parse_add_sub(tokens)
                if tokens[0] != ')':
                    raise ValueError("Mismatched parentheses")
                tokens.pop(0)
                return val
            return parse_add_sub(tokens)

        return parse_parentheses(tokens)

    tokens = parse_expression(expr)
    return evaluate(tokens)
