def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    congruences = [(r % m, m) for r, m in congruences]
    congruences = [(r, m) for r, m in congruences if m > 0]

    if not congruences:
        return (0, 1)

    x, L = congruences[0]
    for r, m in congruences[1:]:
        a, b = x, L
        c, d = r, m

        g = math.gcd(b, d)
        if (c - a) % g != 0:
            return None

        lcm = b // g * d
        k = (c - a) // g
        inv = pow(b // g, -1, d // g)
        x = a + k * inv * b
        x %= lcm
        L = lcm

    return (x, L)
