def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    # Normalize each congruence to r < m and m > 0
    normalized = []
    for r, m in congruences:
        if m <= 0:
            return None
        r = r % m
        normalized.append((r, m))

    # Solve pairwise using the Chinese Remainder Theorem
