def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # program counter
    max_instructions = 1000

    while pc < len(program) and max_instructions > 0:
        instruction = program[pc].split()
        max_instructions -= 1

        if not instruction:
            raise ValueError("Empty instruction")

        cmd = instruction[0]

        if cmd == "PUSH":
            if len(instruction) != 2:
                raise ValueError("PUSH requires exactly one argument")
            try:
                n = int(instruction[1])
                stack.append(n)
            except ValueError:
                raise ValueError("PUSH argument must be an integer")
            pc += 1

        elif cmd == "POP":
            if not stack:
                raise ValueError("POP from empty stack")
            stack.pop()
            pc += 1

        elif cmd == "DUP":
            if not stack:
                raise ValueError("DUP from empty stack")
            stack.append(stack[-1])
            pc += 1

        elif cmd == "SWAP":
            if len(stack) < 2:
                raise ValueError("SWAP requires at least two elements in stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1

        elif cmd == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD requires at least two elements in stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
            pc += 1

        elif cmd == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB requires at least two elements in stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
            pc += 1

        elif cmd == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL requires at least two elements in stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
            pc += 1

        elif cmd == "JMP":
            if len(instruction) != 2:
                raise ValueError("JMP requires exactly one argument")
            try:
                t = int(instruction[1])
                pc = t
            except ValueError:
                raise ValueError("JMP argument must be an integer")

        elif cmd == "JZ":
            if len(instruction) != 2 or not stack:
                raise ValueError("JZ requires exactly one argument and non-empty stack")
            try:
                t = int(instruction[1])
                val = stack.pop()
                pc = t if val == 0 else pc + 1
            except ValueError:
                raise ValueError("JZ argument must be an integer")

        elif cmd == "HALT":
            pc = len(program)

        else:
            raise ValueError(f"Unknown instruction: {cmd}")

    if max_instructions == 0:
        raise RuntimeError("Maximum number of instructions exceeded")

    return stack
