            if len(stack) < 2:
                raise ValueError("SWAP requires at least two values on stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif op == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD requires at least two values on stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)

        elif op == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB requires at least two values on stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)

        elif op == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL requires at least two values on stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)

        elif op == "JMP":
            if len(instruction) != 2:
                raise ValueError("JMP requires exactly one argument")
            try:
                t = int(instruction[1])
            except ValueError:
                raise ValueError(f"Invalid target in JMP: {instruction[1]}")
            pc = t - 1  # pc will be incremented at the end of the loop

        elif op == "JZ":
            if len(instruction) != 2:
                raise ValueError("JZ requires exactly one argument")
            if not stack:
                raise ValueError("JZ on empty stack")
            try:
                t = int(instruction[1])
            except ValueError:
                raise ValueError(f"Invalid target in JZ: {instruction[1]}")
            if stack[-1] == 0:
                stack.pop()
                pc = t - 1  # pc will be incremented at the end of the loop

        elif op == "HALT":
            break

        else:
            raise ValueError(f"Unknown instruction: {op}")

        pc += 1

    if executed >= max_executions:
        raise RuntimeError("Maximum number of instructions executed")

    return stack

