def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    def multiply(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % mod
        return result

    def matrix_pow(mat: list[list[int]], power: int) -> list[list[int]]:
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1  # Identity matrix

        while power > 0:
            if power % 2 == 1:
                result = multiply(result, mat)
            mat = multiply(mat, mat)
            power //= 2
        return result

    if exp == 0:
        return [[0 if i != j else 1 % mod for j in range(n)] for i in range(n)]

    # Normalize the matrix entries modulo mod
    normalized_matrix = [[x % mod for x in row] for row in matrix]
    return matrix_pow(normalized_matrix, exp)
