import re

def tidy_punctuation(text: str) -> str:
    # Step 1: Replace runs of whitespace with single space and trim
    text = re.sub(r'\s+', ' ', text.strip())

    # Step 2: Remove space before punctuation (, . ; : ! ?)
    text = re.sub(r'\s+([,.;\:\!\?])', r'\1', text)

    # Step 3: Add single space after punctuation if followed by a letter
    text = re.sub(r'([,.;\:\!\?])([a-zA-Z])', r'\1 \2', text)

    # Step 4: Capitalize first character and after . ! ?
    words = text.split(' ')
    if words:
        words[0] = words[0].capitalize()
        for i in range(1, len(words)):
            if words[i-1].endswith(('.', '!', '?')):
                words[i] = words[i].capitalize()

    return ' '.join(words)

