import re

def identifier_to_snake(name: str) -> str:
    if not name:
        return ""

    # Replace hyphens with underscores and split into words
    parts = re.split(r'([A-Z][a-z]+|[A-Z]+?|[a-z]+|[0-9]+)', name.replace('-', '_'))

    # Filter out empty strings and join with underscores
    words = [part.lower() for part in parts if part and part != '_']

    # Handle cases where camelCase or PascalCase needs splitting (e.g., 'HTMLParser' -> 'html_parser')
    result = []
    for word in words:
        if word.isupper() and len(word) > 1:
            # Split camelCase or PascalCase words (e.g., 'HTMLParser' -> 'html', 'parser')
            sub_words = re.findall(r'[A-Z]?[a-z]+|[A-Z]+?', word)
            result.extend([s.lower() for s in sub_words if s])
        else:
            result.append(word)

    return '_'.join(result)
