def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end or min_len <= 0:
        return []

    # Filter and normalize busy intervals
    intervals = []
    for start, end in busy:
        if start < end:
            intervals.append((start, end))

    # Sort intervals by start time
    intervals.sort()

    # Merge overlapping or adjacent intervals
    merged = []
    for interval in intervals:
        if not merged:
            merged.append(interval)
        else:
            last_start, last_end = merged[-1]
            current_start, current_end = interval
            if current_start <= last_end:
                # Overlapping or adjacent, merge them
                new_start = last_start
                new_end = max(last_end, current_end)
                merged[-1] = (new_start, new_end)
            else:
                merged.append(interval)

    # Find free slots within day bounds
    free_slots = []
    prev_end = day_start

    for start, end in merged:
        if start > prev_end:
            slot_length = start - prev_end
            if slot_length >= min_len:
                free_slots.append((prev_end, start))
        prev_end = max(prev_end, end)

    # Check the last possible free slot
    if prev_end < day_end:
        slot_length = day_end - prev_end
        if slot_length >= min_len:
            free_slots.append((prev_end, day_end))

    return free_slots
