def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    bins = []
    sorted_sizes = sorted(sizes, reverse=True)

    for size in sorted_sizes:
        if size > capacity:
            raise ValueError("Item size exceeds bin capacity")

        placed = False
        for bin_idx in range(len(bins)):
            if sum(bins[bin_idx]) + size <= capacity:
                bins[bin_idx].append(size)
                placed = True
                break

        if not placed:
            bins.append([size])

    return bins
