def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    teams = {}

    for home, away, hg, ag in results:
        for team in [home, away]:
            if team not in teams:
                teams[team] = {'points': 0, 'goals_scored': 0, 'goals_conceded': 0}

        teams[home]['goals_scored'] += hg
        teams[home]['goals_conceded'] += ag
        teams[away]['goals_scored'] += ag
        teams[away]['goals_conceded'] += hg

        if hg > ag:
            teams[home]['points'] += 3
        elif hg == ag:
            teams[home]['points'] += 1
            teams[away]['points'] += 1
        else:
            teams[away]['points'] += 3

    sorted_teams = sorted(
        teams.items(),
        key=lambda item: (
            -item[1]['points'],
            -(item[1]['goals_scored'] - item[1]['goals_conceded']),
            -item[1]['goals_scored'],
            item[0]
        )
    )

    return [
        (team, stats['points'], stats['goals_scored'] - stats['goals_conceded'], stats['goals_scored'])
        for team, stats in sorted_teams
    ]
