def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    teams = defaultdict(lambda: {'points': 0, 'goals_scored': 0, 'goals_conceded': 0})

    for home, away, home_goals, away_goals in results:
        teams[home]['goals_scored'] += home_goals
        teams[home]['goals_conceded'] += away_goals
        teams[away]['goals_scored'] += away_goals
        teams[away]['goals_conceded'] += home_goals

        if home_goals > away_goals:
            teams[home]['points'] += 3
        elif home_goals == away_goals:
            teams[home]['points'] += 1
            teams[away]['points'] += 1
        else:
            teams[away]['points'] += 3

    league = [
        (
            team,
            stats['points'],
            stats['goals_scored'] - stats['goals_conceded'],
            stats['goals_scored']
        )
        for team, stats in teams.items()
    ]

    league.sort(key=lambda x: (-x[1], -(x[2]), -x[3], x[0]))
    return league

