def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by decreasing profit, maintaining original order for ties
    sorted_jobs = sorted(jobs, key=lambda x: (-x[2], jobs.index(x)))

    # Initialize a list to track occupied slots
    occupied = [False] * (max(job[1] for job in jobs) if jobs else 0)

    # Assign jobs to the highest available slot <= deadline
    for name, deadline, _ in sorted_jobs:
        if deadline < 1:
            continue
        # Find the highest available slot <= deadline
        slot = deadline
        while slot >= 1 and occupied[slot - 1]:
            slot -= 1
        if slot >= 1:
            occupied[slot - 1] = True

    # Collect scheduled jobs in order of slot numbers
    scheduled = []
    for slot in range(1, len(occupied) + 1):
        if occupied[slot - 1]:
            # Find the job assigned to this slot (last assigned job in this slot)
            for name, deadline, _ in reversed(sorted_jobs):
                if deadline >= slot and not occupied[slot - 1]:
                    continue
                # Check if this job was assigned to this slot
                # Re-run assignment logic to verify (since we can't track easily)
                temp_occupied = occupied.copy()
                temp_assigned = False
                for n, d, p in sorted_jobs:
                    if temp_assigned and n == name:
                        break
                    if d >= slot and not temp_occupied[slot - 1]:
                        temp_occupied[slot - 1] = True
                        temp_assigned = True
                if temp_assigned and occupied[slot - 1]:
                    scheduled.append(name)
                    break

    # Alternative approach to track assignments (more efficient)
    occupied = [False] * (max(job[1] for job in jobs) if jobs else 0)
    assignments = {}
    for name, deadline, _ in sorted_jobs:
        if deadline < 1:
            continue
        slot = deadline
        while slot >= 1 and occupied[slot - 1]:
            slot -= 1
        if slot >= 1:
            occupied[slot - 1] = True
            assignments[slot] = name

    # Generate result in order of slot numbers
    return [assignments[slot] for slot in range(1, len(occupied) + 1) if slot in assignments]
