def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    executed = 0
    max_executions = 1000

    while ip < len(program) and executed < max_executions:
        instruction = program[ip].split()
        cmd = instruction[0]

        try:
            if cmd == 'PUSH':
                stack.append(int(instruction[1]))
            elif cmd == 'POP':
                if not stack:
                    return None
                stack.pop()
            elif cmd == 'DUP':
                if not stack:
                    return None
                stack.append(stack[-1])
            elif cmd == 'SWAP':
                if len(stack) < 2:
                    return None
                stack[-1], stack[-2] = stack[-2], stack[-1]
            elif cmd == 'ADD':
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif cmd == 'SUB':
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            elif cmd == 'MUL':
                if len(stack) < 2:
                    return None
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif cmd == 'JMP':
                target = int(instruction[1])
                ip = target - 1  # decrement to account for the increment below
            elif cmd == 'JZ':
                if not stack:
                    return None
                target = int(instruction[1])
                if stack[-1] == 0:
                    ip = target - 1
            else:
                return None  # invalid instruction
        except (IndexError, ValueError):
            return None

        ip += 1
        executed += 1

    return stack if executed < max_executions else None
