def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number or number == '-' or from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Invalid input")

    is_negative = number[0] == '-'
    if is_negative:
        number = number[1:]
    if not number:
        raise ValueError("Invalid input")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    try:
        num = 0
        for c in number:
            if c.lower() not in digits:
                raise ValueError("Invalid digit")
            value = digits.index(c.lower())
            if value >= from_base:
                raise ValueError("Invalid digit for base")
            num = num * from_base + value
    except ValueError:
        raise ValueError("Invalid digit")

    if num == 0:
        return "0"

    result = []
    while num > 0:
        remainder = num % to_base
        result.append(digits[remainder])
        num = num // to_base

    if is_negative:
        result.append('-')

    return ''.join(reversed(result))
