def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36")

    if not number:
        raise ValueError("Empty string provided")

    if number[0] == '-':
        is_negative = True
        num_str = number[1:]
    else:
        is_negative = False
        num_str = number

    if not num_str:
        raise ValueError("Only '-' provided")

    # Validate input characters
    for c in num_str:
        if c.isdigit():
            val = int(c)
        elif c.isalpha():
            val = 10 + ord(c.lower()) - ord('a')
        else:
            raise ValueError(f"Invalid character '{c}' in input")

        if val >= from_base:
            raise ValueError(f"Character '{c}' is not valid for base {from_base}")

    # Convert to decimal
    decimal_value = 0
    for c in num_str:
        if c.isdigit():
            val = int(c)
        else:
            val = 10 + ord(c.lower()) - ord('a')
        decimal_value = decimal_value * from_base + val

    # Handle zero case
    if decimal_value == 0:
        return '0'

    # Convert from decimal to target base
    digits = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        decimal_value = decimal_value // to_base

    result = ''.join(reversed(digits))
    return '-' + result if is_negative else result
