def count_set_bits_range(lo: int, hi: int) -> int:
    def count_set_bits(n: int) -> int:
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    if lo > hi:
        return 0

    def compute(n: int) -> int:
        if n == 0:
            return 0
        k = n.bit_length()
        return (n - (1 << (k - 1)) + 1) + compute(n >> 1)

    return compute(hi) - compute(lo - 1)
