def restore_session(data: bytes) -> Dict[str, Union[int, str, List[Union[int, str]]]]:
    """Restore a user session from serialized bytes.

    Args:
        data: Serialized session data produced by pickle.dumps from a dictionary with
              string keys and values that are integers, strings, or lists of integers/strings.

    Returns:
        Deserialized session dictionary with the same structure as the original.

    Raises:
        pickle.PickleError: If the data cannot be unpickled.
        ValueError: If the unpickled data is not a dictionary or contains invalid types.
    """
    try:
        session = pickle.loads(data)
    except pickle.PickleError as e:
        raise pickle.PickleError(f"Failed to unpickle session data: {e}") from e

    if not isinstance(session, dict):
        raise ValueError("Unpickled data is not a dictionary")

    for key, value in session.items():
        if not isinstance(key, str):
            raise ValueError(f"Session key '{key}' is not a string")

        if not isinstance(value, (int, str, list)):
            raise ValueError(f"Session value for key '{key}' is of invalid type: {type(value)}")

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, (int, str)):
                    raise ValueError(f"List item in session value for key '{key}' is of invalid type: {type(item)}")

    return session
