import pickle

def restore_cache_entry(blob: bytes) -> dict:
    """Restore a dictionary from a zlib-compressed pickle blob.

    Args:
        blob: A bytes object containing a zlib-compressed pickle dump of a dictionary
              with string keys and values that are strings, integers, floats, lists,
              or dictionaries containing the same types.

    Returns:
        The original dictionary that was pickled and compressed.

    Raises:
        pickle.PickleError: If the blob is not a valid pickle.
        zlib.error: If the blob is not valid zlib data.
        ValueError: If the unpickled data is not a dictionary or contains invalid types.
    """
    decompressed = zlib.decompress(blob)
    entry = pickle.loads(decompressed)

    if not isinstance(entry, dict):
        raise ValueError("Unpickled data is not a dictionary")

    def _validate_value(value):
        if isinstance(value, (str, int, float)):
            return True
        if isinstance(value, dict):
            return all(isinstance(k, str) and _validate_value(v) for k, v in value.items())
        if isinstance(value, list):
            return all(_validate_value(v) for v in value)
        return False

    if not all(isinstance(k, str) and _validate_value(v) for k, v in entry.items()):
        raise ValueError("Dictionary contains invalid types")

    return entry

