import re
import operator

def evaluate_expression(expression: str) -> float:
    # Remove all spaces from the expression
    expr = expression.replace(' ', '')

    # Check for empty string
    if not expr:
        raise ValueError("Empty expression")

    # Check for balanced parentheses
    if expr.count('(') != expr.count(')'):
        raise ValueError("Unbalanced parentheses")

    # Validate tokens
    tokens = re.findall(r'(\d+\.?\d*|\.\d+|[-+*/^()])', expr)
    for token in tokens:
        if token == '^':
            raise ValueError("Use '**' for exponentiation")
        if token not in ('+', '-', '*', '/', '**', '(', ')'):
            try:
                float(token)
            except ValueError:
                raise ValueError(f"Invalid token: {token}")

    # Replace ** with ^ for easier parsing (but we'll handle it as ** later)
    expr = expr.replace('**', '^')

    # Convert infix to postfix notation (Reverse Polish Notation)
    precedence = {'^': 4, '*': 3, '/': 3, '+': 2, '-': 2}
    output = []
    operators = []

    i = 0
    while i < len(expr):
        if expr[i] == ' ':
            i += 1
            continue
        if expr[i] in '()+-*/^':
            if expr[i] == '-' and (i == 0 or expr[i-1] in '+-*/^('):
                # Handle unary minus
                output.append('u-')
                i += 1
                continue
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[expr[i]]):
                output.append(operators.pop())
            operators.append(expr[i])
            i += 1
        else:
            # Parse numbers (including decimals and negative numbers)
            j = i
            if expr[i] == '-':
                j += 1
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            output.append(expr[i:j])
            i = j

    while operators:
        op = operators.pop()
        if op == '(':
            raise ValueError("Unbalanced parentheses")
        output.append(op)

    # Evaluate postfix expression
    stack = []
    ops = {
        '+': operator.add,
        '-': operator.sub,
        '*': operator.mul,
        '/': operator.truediv,
        '^': operator.pow,
        'u-': lambda x: -x
    }

    for token in output:
        if token.replace('.', '').isdigit() or (token[0] == '-' and token[1:].replace('.', '').isdigit()):
            stack.append(float(token))
        else:
            if len(stack) < 2 and token != 'u-':
                raise ValueError("Invalid expression")
            if token == 'u-':
                if not stack:
                    raise ValueError("Invalid expression")
                a = stack.pop()
                stack.append(ops[token](a))
            else:
                b = stack.pop()
                a = stack.pop()
                try:
                    result = ops[token](a, b)
                except ZeroDivisionError:
                    raise ZeroDivisionError("Division by zero")
                stack.append(result)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack[0]
