import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https:// (case-insensitive)
    if not re.match(r'^https://', url, re.IGNORECASE):
        return False

    # Check for backslashes, spaces, or control characters
    if re.search(r'[\\ \x00-\x1f\x7f]', url):
        return False

    # Extract host and port
    match = re.match(r'^https://([^/@]+)(?::(\d+))?/?$', url, re.IGNORECASE)
    if not match:
        return False
    host_port = match.group(1)
    port = match.group(2)

    # Check port if present
    if port and port != '443':
        return False

    # Extract host (remove user:pass@ if present)
    host = re.sub(r'^.*@', '', host_port)

    # Check for localhost or .localhost
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    # Check DNS name format
    if not re.match(r'^([a-zA-Z0-9-]+\.)+[a-zA-Z0-9-]+\.[a-zA-Z]+$', host):
        return False

    # Check for empty labels or invalid characters
    if re.search(r'[a-zA-Z0-9-]*\.\.|[a-zA-Z0-9-]*\.$', host):
        return False

    # Check each label is not empty and only contains valid characters
    labels = host.split('.')
    if len(labels) < 2:
        return False
    for label in labels[:-1]:
        if not label or not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False
    if not labels[-1] or not re.match(r'^[a-zA-Z]+$', labels[-1]):
        return False

    return True
