import ipaddress

def is_public_ip(ip_str: str) -> bool:
    """Check if the given string is a publicly routable IP address in standard text form.

    Returns:
        bool: True if the IP is valid and publicly routable, False otherwise.
    """
    try:
        ip = ipaddress.ip_address(ip_str)
    except ValueError:
        return False

    # Check for public routable IP
    if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved:
        return False

    # Check for unspecified (0.0.0.0/0 or ::/0)
    if ip.is_unspecified:
        return False

    # Check for documentation (192.0.2.0/24, 198.51.100.0/24, 203.0.113.0/24)
    if ip.is_documentation:
        return False

    # Check for shared address space (100.64.0.0/10)
    if ip.version == 4 and ip >= ipaddress.IPv4Address("100.64.0.0") and ip <= ipaddress.IPv4Address("100.127.255.255"):
