from jinja2 import Environment, BaseLoader

def render_mail_merge(template: str, recipients: list[dict]) -> list[str]:
    env = Environment(loader=BaseLoader())
    env.trim_blocks = False
    env.lstrip_blocks = False
    env.newline_sequence = '\n'

    def render_single(recipient: dict) -> str:
        try:
            return env.from_string(template).render(**recipient)
        except Exception:
            # Fallback to simple string replacement if Jinja2 fails
            for key in recipient:
                placeholder = f"{{{{ {key} }}}}".replace(" ", "")
                template = template.replace(placeholder, str(recipient[key]))
            return template

    return [render_single(recipient) for recipient in recipients]
