        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return []

    books = []
    for book_elem in root.findall('book'):
        book_id = book_elem.get('id', '')
        title_elem = book_elem.find('title')
        author_elem = book_elem.find('author')

        title = title_elem.text if title_elem is not None and title_elem.text is not None else ""
        author = author_elem.text if author_elem is not None and author_elem.text is not None else ""

        books.append({
            'id': book_id,
            'title': title,
            'author': author
        })

    return books

