def get_users_by_ids(conn, ids: list) -> list[tuple]:
    if not ids:
        return []

    # Convert all IDs to integers and remove duplicates while preserving order
    unique_ids = []
    seen = set()
    for id_val in ids:
        try:
            id_int = int(id_val)
            if id_int not in seen:
                seen.add(id_int)
                unique_ids.append(id_int)
        except ValueError:
            continue

    if not unique_ids:
        return []

    # Create a parameterized query with placeholders
    placeholders = ','.join(['?'] * len(unique_ids))
    query = f"SELECT id, username FROM users WHERE id IN ({placeholders}) ORDER BY id"

    cursor = conn.cursor()
    cursor.execute(query, unique_ids)
    return cursor.fetchall()
